/// The greatest common divisor of two integers.
int gcd(int a, int b) {
  // Handle zero cases explicitly to avoid infinite recursion or division by zero later.
  if (a == 0 && b != 0) return b.abs();   // gcd(0,b)=|b|.
  if (a != 0 && b == 0) return a.abs();   // gcd(a,0)=|a|.
  if (a == 0 && b == 0) throw ArgumentError("gcd(0,0) is undefined.");

  // Work with absolute values so we can safely use modulo; sign doesn't affect GCD.
  var x = a.abs();
  var y = b.abs();

  while (y != 0) {
    var r = x % y;
    x = y;
    y = r;
  }
  return x;
}

