bool correctBracketing(String brackets) {
  int openCount = 0;

  for (int i = 0; i < brackets.length; ++i) {
    if (brackets[i] == '<') {
      openCount++;
    } else if (openCount > 0 && brackets[i] == '>') {
      openCount--;
