/// Returns the largest prime factor of [n] (for positive integers only).
int largestPrimeFactor(int n) {
  if (n <= 1 || n < 0) throw ArgumentError('$n must be a positive integer > 1');

  var divisor = 2;
  while (divisor * divisor <= n) {
    while (n % divisor == 0) {
      n ~/= divisor;
    }
    divisor += 1;
  }

  return n.max(divisor - 1);
