/// Returns the value of a(n) (the sequence defined by a(0)=a(1)=0, a(3)=a(4)=1,
/// and otherwise a(n+3)=a(n)+a(n+1)).
int fibfib(int n) {
  if (n <= 1) return 0;      // base cases for n = 0 or 1
  if (n == 2 || n == 3) return 0;   // a(2)=a(3)=0 per definition
  if (n == 4 || n == 5) return 1;   // a(4)=a(5)=1 per definition

  // For larger n we can use an iterative DP that stores only needed values.
  // The recurrence uses indices spaced three apart:
  //   a(i) depends on i-3 and i-1.
  List<int> memo = List.generate(6, (_) => -1);
  memo[0] = 0;
  memo[1] = 0;
  memo[2] = 0;
  memo[3] = 0;
  memo[4] = 1;
  memo[5] = 1;

  for (int i = 6; i <= n; ++i) {
    memo[i % 6] = memo[(i - 3) % 6] + memo[(i - 1) % 6];
  }
  return memo[n % 6];
}

