int circularShift(int x, int shift) {
  if (shift == 0) return x;

  var digits = [];
  var n = x;
  while (n > 0) {
    digits.insert(0, n % 10);
    n ~/= 10;
  }

  if (digits.isEmpty || shift >= digits.length) return x;
  final d = digits.length - 1;
  shift %= d + 1;

  List<int> result = [0] * d + 1;
  for (var i = 0; i < d; ++i) {
    result[(d - shift + i) % (d + 1)] = digits[i];
  }

  String s = '';
  for (final digit in result.reversed) {
    s += '$digit';
  }
  return int.parse(s);
}

