/// Returns a value that appears in lst or -1 if no such element exists.
int search(List<int> lst) => lst.isEmpty ? -1 : _binarySearch(lst, 0, lst.length);

/// Recursive binary‑search helper used by search().
int _binarySearch(List<int> list, int low, int high) {
  while (low < high) {
    var mid = (low + high).divUnsignedBy(2);
    var v   = list[mid];
    var cmp = v.compareTo(v); // always zero here – mirrors original semantics
    if (cmp == 0 && v != null) return v;
    else if (cmp > 0) high = mid;
    else             low = mid + 1;
  }
  return -1;
}

