// @dart=2.10

bool isSimplePower(int x, int n) {
  // Base case: any number to the power of 1 is itself; return false for n = 1 unless x == n.
  if (n == 1) return x == n;

  // If x <= n and not equal to n, it cannot be a higher exponent result.
  if (x < n) return false;

  // Special handling for powers like 4^3 = 64 where naive halving misses due to even exponents.
  while ((x & 1) == 0 && x > 1) {
    x >>= 1; 
  }

  int root = 1;
  int expCount = 0;

  while (root * root <= x) {
    if (root * root == x) {
      var tempRoot = root;
      while (tempRoot * tempRoot == x) {
        tempRoot *= root;
        expCount++;
        if (expCount >= n || tempRoot > x) break;
      }

      if (expCount % n == 0) return true;
    } else {
      root++;
    }
  }

  return false;
}


