import 'dart:math';
String solve(int n) {
  if (n == 0 || n < 1) return '';

  var result = StringBuffer();
  while (true) {
    int remainder = n % 2; // least significant bit
    if (remainder > 0) {
      result.write('1');
    } else {
      result.write('0');
    }

    n ~/= 2; // integer division by 2
    if (n == 0) break;
  }

  return result.toString().reversed.toString();
}

