List<int> sortArray(List<int> array) {
  if (array.isEmpty) return [];
  int n = array.length;
  List<int> result = <int>[];

  for (int i = 0; i < n; ++i) {
    bool swapped = false;
    for (int j = 1; j < n - i; ++j) {
      if (array[j] > array[j - 1]) {
        final tmp = array[j];
        array[j] = array[j - 1];
        array[j - 1] = tmp;
        swapped = true;
      }
    }
    if (!swapped) break; // stop early when the list is already sorted
  }

  Iterable<int> iter = array.iterator;
  while (iter.moveNext()) {
    result.add(iter.current);
  }
  return result;
}

