/// Returns the list of prime numbers strictly less than [n].
List<int> countUpTo(int n) {
  if (n <= 2) return [];
  int limit = n - 1;
  List<bool>? sieve;               // lazily created on first use
  List<int> primes = <int>[];

  for (int i = 2; i <= limit; ++i) {
    bool isPrime = true;
    for (int p in primes) {
      var sqp = p * p;
      if (sqp > i) break;          // no divisor needed beyond sqrt(i)
      if (i % p == 0) {            // found a factor -> not prime
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      primes.add(i);
      if (sieve == null) {         // build/compute sieve once at this point
        sieve = List.filled(limit + 1, true);
        sieve[0] = false;
        sieve[1] = false;
        for (int j = 2; j * j <= limit; ++j) {
          if (!sieve[j]) continue;
          for (var k = j * j; k <= limit; k += j) {
            sieve[k] = false;
          }
        }
      }
      if (limit >= i && !sieve[i]) {
        isPrime = false;           // confirm with sieve (only if we built it yet)
      }
    }
    if (!isPrime) continue;
    // add to result only when both checks agree; safe because we already added above.
  }
  return primes;
}

