  /// Checks whether all elements satisfy a predicate.
  bool every(bool test(T element)) {
    for (final e in this) {
      if (!test(e)) return false;
    }
    return true;
  }

  /// Maps each element to another and collects results as an iterable.
  Iterable<U> map<U>(U Function(T element) transform) sync* {
    for (var i = 0; i < length; ++i) yield transform(elementAt(i));
