  digits.reversed.toList();

  String numStr = digits.join('');
  String reversedNumStr = numStr.split('').reversed.join('');

  bool isPalindromic = numStr == reversedNumStr;

  // Find next palindrome by checking adjacent pairs
  if (!isPalindromic) {
    for (int i = 0; i < digits.length - 2; i++) {
      var pair = [digits[i], digits[i + 1]];

      // Check if current pair forms a valid palindrome pattern
      if (pair[0] == pair[1]) {
        // This means we can increment this position and create new palindromes

        int incrementedPair = pair[0] * 10 + pair[0] + 1; // Incremented odd palindrome
        int decrementedPair = pair[0] * 10 + pair[0] - 1; // Decrementing odd palindrome

        // Generate all possible combinations with these values
        List<List<int>> possibilities = [];

        // Add both incremented and decremented versions of each pair
