class CountNums {
  static int countNums(List<int> arr) {
    final result = <int>[];

    for (final num in arr) {
      if (num > 0 && isPrime(num)) {
        result.add(num);
      } else if (isEven(num)) {
        continue; // Skip even numbers that aren't prime.
      } else if (isOdd(num)) {
        continue; // Skip odd numbers that aren't prime.
      }
    }

    return result.length;
  }

  /// Checks whether a given integer is an even number.
  static bool isEven(int n) => n % 2 == 0;

  /// Checks whether a given integer is an odd number.
  static bool isOdd(int n) => !isEven(n);

  /// Determines if the specified [n] is a prime number. A prime number 
  /// is greater than 1 and has no positive divisors other than 1 and itself.
  static bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;

    if (n % 2 == 0 || n % 3 == 0) return false;

    var i = 5;
    while (i * i <= n) {
      if (n % i == 0 || n % (i + 2) == 0) return false;
      i += 6;
    }
    return true;
  }
}

