          balls.swap(i, i - 1);
          break;
        } else if ((balls[i] & 1) == 1 && (balls[i] >> 1) == i) {
          balls.removeAt(i);
          break;
        }
      }
    }

    for (int j = 0; j < balls.length; j++) {
      if (balls[j] != j + 1) return false;
    }

    return true;
