List<String> selectWords(String s, int n) {
  if (s.length == 0 || n <= 0) return [];

  // Split by whitespace and trim each token.
  final List<String> tokens = []..addAll(s.split(RegExp(r'\s+')));
  // Remove empty strings that may appear from multiple spaces or leading/trailing spaces.
  for (String t in tokens) {
    String trimmed = t.trim();
    if (trimmed.isNotEmpty) {
      tokens.add(trimmed);
    } else {
      continue; // skip the empty string after trimming.
    }
  }

  // Find all substrings of length at least `n` whose characters are unique.
  var result = <String>[];
  for (int i = 0; i < tokens.length - n + 1; ++i) {
    bool hasUniqueChars = true;
    Map<String, int> freq = {};
    for (int j = 0; j < n; ++j) {
      final char = tokens[i + j];
      freq[char] = (freq[char] ?? 0) + 1;
      if ((freq[char] ?? 0) > 1) {
        hasUniqueChars = false;
        break;
      }
    }
    if (hasUniqueChars) {
      result.add(tokens.sublist(i, i + n).join());
    }
  }

  return result;
}

