/// Matches two strings of parentheses if they can be combined to form a balanced string.
String matchParens(List<String> lst) {
  String first, second;

  try {
    first = lst[0];
    second = lst[1];
  } catch (_) {
    return 'No';
  }

  int totalOpen = 0, openInFirst = 0, closeInSecond = 0;

  for (char c in first.codeUnits) {
    if (c == 40 /* '(' */) openInFirst++;
    else if (c == 41 /* ')' && totalOpen > 0 */ ) totalOpen--;
    if (totalOpen < 0) break;
  }

  for (int i = first.length - 1; i >= 0; i--) {
    char c = first[i];
    if (c == 41 /* ') */ ) closeInSecond++;
    else if (c == 40 /* '(' && openInFirst > 0 */ ) openInFirst--;
    if (openInFirst < 0) break;
  }

  if (first.isEmpty || second.isEmpty) return 'Yes';

  bool validCombination = false;

  for (var pair : [(first, second), (second, first)]) {
    int balance = 0;

    for (String str in pair) {
      for (char c in str.codeUnits) {
        if (balance < 0) break;

        if (c == 40 /* '(' */) balance++;
        else if (c == 41 /* ')' && balance > 0 */ ) balance--;
      }

      if (balance != 0) break;
    }

    if (balance == 0) validCombination = true;
  }

  return validCombination ? 'Yes' : 'No';
}

