import 'dart:math' show min;

List<int> maximum(List<int> arr, int k) {
  if (arr.length <= k) return arr.toList(); // copy to ensure distinct list

  List<int> maxSlidingWindow = [];
  var queue = <int>[];

  for (var i = 0; i < arr.length; i++) {
    // Remove elements outside the current window
    while (queue.isNotEmpty && queue.first < i - k + 1) {
      queue.removeAt(0);
    }

    // Maintain decreasing order in the deque by removing smaller elements from the end
    while (queue.isNotEmpty && arr[queue.last] <= arr[i]) {
      queue.removeLast();
    }

    // Add the index of current element to the deque
    queue.add(i);

    // Start adding to result once we have processed at least 'k' elements
    if (i >= k - 1) {
      maxSlidingWindow.add(arr[queue.first]);
    }
  }

  return maxSlidingWindow;
}

