  if (lst.isEmpty || lst.length == 1) return true;

  // Use a map to count occurrences of each element and check for duplicates.
  final Map<int, int> frequency = {};
  for (final item in lst) {
    frequency[item] = (frequency[item] ?? 0) + 1;
