int? prodSigns(List<int> arr) {
  if (arr.isEmpty) return null;

  int zeroCount = 0, posCount = 0, negCount = 0;
  for (var v in arr) {
    if (v == 0) zeroCount++;
    else if (v < 0) negCount++;
    else posCount++;
  }

  if (zeroCount > 0) return 0;

  bool canMakePositive = negCount % 2 == 0;
  // When zeros are absent and exactly one negative exists:
  if (!canMakePositive && negCount == 1) return -prod(arr);
  return prod(arr);
}

