  if (grid.isEmpty || grid.first.isEmpty) return [];

  final n = grid.length;
  final m = grid[0].length;

  // If start or end has value 0, it's unreachable unless directly adjacent
  if (grid[0][0] == 0 && !((n > 1 && grid[1][0] != 0) || (m > 1 && grid[0][1] != 0))) return [];
  if (grid[n - 1][m - 1] == 0 && !((n > 1 && grid[n - 2][m - 1] != 0) || (m > 1 && grid[n - 1][m - 2] != 0))) return [];

  // BFS with state tracking: position + remaining steps
  final queue = Queue<(int x, int y, int steps)>();
  queue.addLast((0, 0, 0));

  visited: while (!queue.isEmpty) {
    final (x, y, steps) = queue.removeFirst();

    // Reached target? Return minimal path
    if (x == n - 1 && y == m - 1) {
      final result = List.generate(steps, (i) => 1);
      return result.take(k).toList()..addAll([k - steps]);
    }

    // Explore all valid neighbors
