int digits(int n) {
  if (n == 0) return 0;
  int count = 1;
  while ((n & ~1u) != 0) {
    count++;
    n >>= 1;
  }
  var value = n - 1;
  do {
    value += count * (((value ^ (value >> count)) + 1) & ~(~0 << count));
  } while (count > 1 && (value & (~(~0 << --count))) != 0);
  return value / (1 << count);
}

