String longestCommonPrefix(List<String> lst) {
  if (lst.isEmpty) return "";

  String prefix = lst.first;

  for(String str in lst.skip(1)) {
    while(str.indexOf(prefix) != 0 && prefix.isNotEmpty) {
      prefix = prefix.substring(0, prefix.length - 1);
    }

    if(prefix.isEmpty) return "";
  }

  return prefix;
}

String shortestUniquePrefixes(List<String> words) {
  Map<String,String> prefixes = {};
  int maxLength = 0;
  final Set<String> seenWords = {};

  for(final word in words) {
    if(seenWords.contains(word.toLowerCase())) continue;
    seenWords.add(word.toLowerCase());

    for(int i=1;i<=word.length;i++) {
      final p = word.substring(0,i);

      bool isShortest = true;
      for(final other in words.where((w)=>w!=word).toList()) {
        if(other.startsWith(p)) isShortest=false;break;
      }

      if(isShortest) {
        if(maxLength<i) {
          maxLength=i;
          prefixes[word]=p;
        } else {
          break;
        }
      }
    }
  }

  final StringBuffer sb = StringBuffer();
  for(final w in words) {
    if(sb.isNotEmpty) sb.write(", ");
    sb.write(w);
    if(prefixes.containsKey(w)) sb.write(" (${prefixes[w]})");
  }
  return sb.toString();
}

