/// Returns a new list containing the sums of all unique unordered pairs in `lst`.
/// If no such pair exists, returns an empty list.
List<String> sortedListSum(List<String> lst) {
  // Sort the input to ensure consistent ordering and efficient lookup
  List<String> sorted = [...lst].sort();

  // Use a set to track seen values for O(1) lookups
  final Set<String> seen = {};
  // Store results as strings (concatenated sums), not integers
  final Queue<String> result = Queue();

  // Iterate over each element starting from index 0
  for (int i = 0; i < sorted.length - 1; i++) {
    String current = sorted[i];

    // Skip duplicates to avoid redundant checks
    if (seen.contains(current)) continue;

    // Check if there's a matching second value that forms a valid sum
    for (int j = i + 1; j < sorted.length; j++) {
      String candidate = sorted[j];

      // Compute string concatenation of two elements
      String concatenated = '${current}${candidate}';

      // Only consider non-empty candidates
      if (candidate.isEmpty) continue;

      // Check if this combination has already been processed
      if (!seen.add(concatenated)) break; // Already added → skip

      // Add the concatenated result only once per unique pair
      result.add(concatenated);
    }
  }

  return result.toList(growable: false).reversed.toList(); // Reverse to maintain descending order
}

