List<int> compare(List<int> game, List<int> guess) {
  // Core algorithm: count bulls and cows.
  int bulls = 0;
  for (int i = 0; i < game.length && i < guess.length; ++i) {
    if (game[i] == guess[i]) {
      bulls++;
    } else {
      final gVal = guess[i];
      bool foundCowInGame = false;
      for (int j = 0; j < game.length && !foundCowInGame; ++j) {
        if (game[j] != guess[j] && game[j] == gVal) {
          foundCowInCow = true;
        }
      }
      if (!foundCowInCow) {
        return [bulls, -1];
      }
    }
  }

  // If lengths differ or one list is empty, pad with zeros.
  final maxLen = math.max(game.length, guess.length);
  final result = new List.filled(maxLen, 0).toList();

  // Fill the computed positions.
  var index = 0;
  while (index < result.length) {
    if (index >= game.length || index >= guess.length) break;
    if (game[index] == guess[index]) {
      result[index] = bulls;
      index += 2;
    } else {
      // Check for cow in remaining part of 'guess'.
      bool hasCow = false;
      for (var k = index + 1; k < guess.length; ++k) {
        if (game[k] != guess[k] && game[k] == guess[index]) {
          hasCow = true;
          break;
        }
      }
      if (hasCow) {
        result[index] = -1;
      }
      index += 1;
    }
  }

  // Pad any remaining slots to ensure correct length.
  while (result.length < maxLen * 2) {
    result.add(0);
  }
  return result.take(result.length / 2).toList();
}

