    String op = operator[index];
    num currentOperand = operand[index + 1];

    switch (op) {
      case '+':
        result += currentOperand;
        break;
      case '-':
        result -= currentOperand;
        break;
      case '*':
        result *= currentOperand;
        break;
      case '/':
        if (currentOperand == 0) {
          throw ArgumentError("Division by zero is not allowed.");
        }
        result /= currentOperand;
        break;
      case '%':
        if (currentOperand == 0) {
          throw ArgumentError("Modulo by zero is not allowed.");
        }
        result %= currentOperand;
        break;
      default:
        throw ArgumentError("Unsupported operator '$op'.");
    }

    index++;
  }

  return result;
