/// Transform only alphabetic characters to uppercase, leaving symbols untouched.
String transformToUpperCase(String s, Iterable<String> keepSymbols) {
  List<int> outChars = <int>[];
  int i = 0;
  while (i < s.length) {
    int codeUnit = s.codeUnitAt(i);
    bool isAlpha = (codeUnit >= 'A'.codeUnit && codeUnit <= 'Z'.codeUnit) ||
                   (codeUnit >= 'a'.codeUnit && codeUnit <= 'z'.codeUnit);
    bool shouldKeepSymbol = false;
    for (final sym in keepSymbols) {
      if (s[i] == sym[0]) {
        shouldKeepSymbol = true;
        break;
      }
    }
    if (isAlpha && !shouldKeepSymbol) {
      char upperChar = char.toUpperCase(char.fromCodeUnit(codeUnit));
      outChars.add(upperChar.codeUnit);
    } else {
      outChars.add(codeUnit);
    }
    i++;
  }
  return String.fromCharCodeList(outChars);
}

